// convert_contract.cpp — consumer test for the convert API (ascii/binary roundtrip).
//
// Writes a minimal PrusaSlicer-style ASCII G-code sample (the convert parser
// requires a "; generated by PrusaSlicer ..." producer line plus printer /
// print / slicer metadata, otherwise from_ascii_to_binary returns
// InvalidAsciiGCodeFile), converts it to binary bgcode with
// MeatPackComments encoding + upstream compression mix (exercises binarize +
// core + vendored heatshrink/zlib through convert), converts it back and
// checks the roundtrip. Any failed CHECK makes the process exit nonzero,
// so exit 0 means all 5 checks passed.
#include <LibBGCode/convert/convert.hpp>
#include <LibBGCode/core/core.hpp>

#include <cstdio>
#include <fstream>
#include <iostream>
#include <sstream>
#include <string>

static int g_passed = 0;
static int g_failed = 0;

#define CHECK(cond, label)                                                     \
    do {                                                                       \
        if (cond) {                                                            \
            ++g_passed;                                                        \
            std::cout << "CHECK pass: " << label << "\n";                      \
        } else {                                                               \
            ++g_failed;                                                        \
            std::cout << "CHECK FAIL: " << label << "\n";                      \
        }                                                                      \
    } while (0)

namespace {

// Minimal input accepted by convert::from_ascii_to_binary: producer header
// + one printer key (printer_model) + one print key (filament used [g]) +
// a one-entry prusaslicer_config block (slicer metadata) + real G-code.
// Mirrors tests/data/mini_cube_a.gcode header shape at the same commit.
const char *kSampleGcode =
    "; generated by PrusaSlicer 2.6.0\n"
    "\n"
    "\n"
    "; printer_model = MINI\n"
    "; filament_type = PETG\n"
    "; nozzle_diameter = 0.4\n"
    "; temperature = 240\n"
    "; filament used [g] = 3.01\n"
    "; estimated printing time (normal mode) = 32m 6s\n"
    "\n"
    "G1 X10 Y20 E1 F6000\n"
    "; trailing comment\n"
    "\n"
    "; prusaslicer_config = begin\n"
    "; fill_density = 15%\n"
    "; prusaslicer_config = end\n";

std::string read_file(const char *path) {
    std::ifstream in(path, std::ios::binary);
    std::ostringstream stream;
    stream << in.rdbuf();
    return stream.str();
}

long file_size(const char *path) {
    std::ifstream in(path, std::ios::binary | std::ios::ate);
    if (!in.good()) {
        return -1;
    }
    return static_cast<long>(in.tellg());
}

} // namespace

int main() {
    const char *ascii_path = "convert_contract_sample.gcode";
    const char *binary_path = "convert_contract_sample.bgcode";
    const char *roundtrip_path = "convert_contract_roundtrip.gcode";

    {
        std::ofstream out(ascii_path, std::ios::binary);
        if (!out.good()) {
            std::cout << "CHECK FAIL: cannot write sample gcode\n";
            return 1;
        }
        out << kSampleGcode;
    }

    // Same mix as upstream convert_tests (ascii->binary cases): slicer
    // metadata deflated via zlib, gcode compressed via vendored heatshrink
    // 12_4, so the consumer build proves both vendored edges link.
    bgcode::binarize::BinarizerConfig config;
    config.checksum = bgcode::core::EChecksumType::CRC32;
    config.compression.file_metadata = bgcode::core::ECompressionType::None;
    config.compression.print_metadata = bgcode::core::ECompressionType::None;
    config.compression.printer_metadata = bgcode::core::ECompressionType::None;
    config.compression.slicer_metadata = bgcode::core::ECompressionType::Deflate;
    config.compression.gcode = bgcode::core::ECompressionType::Heatshrink_12_4;
    config.gcode_encoding = bgcode::core::EGCodeEncodingType::MeatPackComments;
    config.metadata_encoding = bgcode::core::EMetadataEncodingType::INI;

    FILE *src = std::fopen(ascii_path, "rb");
    FILE *dst = std::fopen(binary_path, "wb");
    if (src == nullptr || dst == nullptr) {
        std::cout << "CHECK FAIL: cannot open conversion files\n";
        if (src != nullptr) {
            std::fclose(src);
        }
        if (dst != nullptr) {
            std::fclose(dst);
        }
        return 1;
    }
    const bgcode::core::EResult to_binary =
        bgcode::convert::from_ascii_to_binary(*src, *dst, config);
    std::fclose(src);
    std::fclose(dst);
    if (to_binary != bgcode::core::EResult::Success) {
        std::cout << "DIAG ascii_to_binary result: "
                  << static_cast<int>(to_binary) << " ("
                  << bgcode::core::translate_result(to_binary) << ")\n";
    }
    CHECK(to_binary == bgcode::core::EResult::Success, "ascii_to_binary success");

    // A valid conversion must produce a non-empty bgcode file (guards the
    // empty-fixture class of false passes: exit 0 on empty output).
    CHECK(file_size(binary_path) > 0, "bgcode output non-empty");

    src = std::fopen(binary_path, "rb");
    dst = std::fopen(roundtrip_path, "wb");
    if (src == nullptr || dst == nullptr) {
        std::cout << "CHECK FAIL: cannot open back-conversion files\n";
        if (src != nullptr) {
            std::fclose(src);
        }
        if (dst != nullptr) {
            std::fclose(dst);
        }
        return 1;
    }
    const bgcode::core::EResult to_ascii =
        bgcode::convert::from_binary_to_ascii(*src, *dst, true);
    std::fclose(src);
    std::fclose(dst);
    if (to_ascii != bgcode::core::EResult::Success) {
        std::cout << "DIAG binary_to_ascii result: "
                  << static_cast<int>(to_ascii) << " ("
                  << bgcode::core::translate_result(to_ascii) << ")\n";
    }
    CHECK(to_ascii == bgcode::core::EResult::Success, "binary_to_ascii success");

    const std::string roundtrip = read_file(roundtrip_path);
    CHECK(roundtrip.find("G1 X10") != std::string::npos, "roundtrip keeps G1 X10");
    CHECK(roundtrip.find("Y20") != std::string::npos, "roundtrip keeps Y20");

    std::cout << "RESULT convert_contract: " << g_passed << "/"
              << (g_passed + g_failed) << " passed\n";
    return g_failed == 0 ? 0 : 1;
}
